import{_ as l,a0 as p,w as r,s as d,I as i,x as a,a1 as t,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"循序渐进学习如何在 MariaDB 中配置主从复制 | LCTT x X-CMD","titleTemplate":false,"description":"循序渐进学习如何在 MariaDB 中配置主从复制 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"循序渐进学习如何在 MariaDB 中配置主从复制 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"循序渐进学习如何在 MariaDB 中配置主从复制 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171112 Step by Step guide for creating Master Slave replication in MariaDB","title":"循序渐进学习如何在 MariaDB 中配置主从复制","tag":"201802","desc":""},"relativePath":"201802/20171112 Step by Step guide for creating Master Slave replication in MariaDB.md","filePath":"[post].md"}'),h={name:"201802/20171112 Step by Step guide for creating Master Slave replication in MariaDB.md"};function g(c,s,k,b,u,m){const e=p("Link");return r(),d("div",null,[s[21]||(s[21]=i("h1",{id:"循序渐进学习如何在-mariadb-中配置主从复制",tabindex:"-1"},[a("循序渐进学习如何在 MariaDB 中配置主从复制 "),i("a",{class:"header-anchor",href:"#循序渐进学习如何在-mariadb-中配置主从复制","aria-label":"Permalink to “循序渐进学习如何在 MariaDB 中配置主从复制”"},"​")],-1)),i("p",null,[s[2]||(s[2]=a("在我们前面的教程中，我们已经学习了 ",-1)),t(e,{href:"https://linux.cn/article-8320-1.html"},{default:n(()=>[...s[0]||(s[0]=[a("如何安装和配置 MariaDB",-1)])]),_:1}),s[3]||(s[3]=a("，也学习了 ",-1)),t(e,{href:"https://linux.cn/article-9306-1.html"},{default:n(()=>[...s[1]||(s[1]=[a("管理 MariaDB 的一些基础命令",-1)])]),_:1}),s[4]||(s[4]=a("。现在我们来学习，如何在 MariaDB 服务器上配置一个主从复制。",-1))]),s[22]||(s[22]=i("p",null,"复制是用于为我们的数据库创 建多个副本，这些副本可以在其它数据库上用于运行查询，像一些非常繁重的查询可能会影响主数据库服务器的性能，或者我们可以使用它来做数据冗余，或者兼具以上两个目的。我们可以将这个过程自动化，即主服务器到从服务器的复制过程自动进行。执行备份而不影响在主服务器上的写操作。",-1)),s[23]||(s[23]=i("p",null,"因此，我们现在去配置我们的主-从复制，它需要两台安装了 MariaDB 的机器。它们的 IP 地址如下：",-1)),s[24]||(s[24]=i("ul",null,[i("li",null,[i("strong",null,"主服务器 -"),a(" 192.168.1.120 "),i("strong",null,"主机名 -"),a(" master.ltechlab.com")]),i("li",null,[i("strong",null,"从服务器 -"),a(" 192.168.1.130 "),i("strong",null,"主机名 -"),a(" slave.ltechlab.com")])],-1)),i("p",null,[s[6]||(s[6]=a("MariaDB 安装到这些机器上之后，我们继续进行本教程。如果你需要安装和配置 MariaDB 的教程，请查看",-1)),t(e,{href:"https://linux.cn/article-8320-1.html"},{default:n(()=>[...s[5]||(s[5]=[i("strong",null,"这个教程",-1)])]),_:1}),s[7]||(s[7]=a("。",-1))]),s[25]||(s[25]=o(`<h3 id="第-1-步-主服务器配置" tabindex="-1">第 1 步 - 主服务器配置 <a class="header-anchor" href="#第-1-步-主服务器配置" aria-label="Permalink to “第 1 步 - 主服务器配置”">​</a></h3><p>我们现在进入到 MariaDB 中的一个命名为 <code>important</code> 的数据库，它将被复制到我们的从服务器。为开始这个过程，我们编辑名为 <code>/etc/my.cnf</code> 的文件，它是 MariaDB 的配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/my.cnf</span></span></code></pre></div><p>在这个文件中找到 <code>[mysqld]</code> 节，然后输入如下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[mysqld]</span></span>
<span class="line"><span>log-bin</span></span>
<span class="line"><span>server_id=1</span></span>
<span class="line"><span>replicate-do-db=important</span></span>
<span class="line"><span>bind-address=192.168.1.120</span></span></code></pre></div><p>保存并退出这个文件。完成之后，需要重启 MariaDB 服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart mariadb</span></span></code></pre></div><p>接下来，我们登入我们的主服务器上的 Mariadb 实例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><p>在它上面创建一个命名为 <code>slaveuser</code> 的为主从复制使用的新用户，然后运行如下的命令为它分配所需要的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STOP SLAVE;</span></span>
<span class="line"><span>GRANT REPLICATION SLAVE ON *.* TO  &#39;slaveuser&#39;@&#39;%&#39; IDENTIFIED BY &#39;iamslave&#39;;</span></span>
<span class="line"><span>FLUSH PRIVILEGES;</span></span>
<span class="line"><span>FLUSH TABLES WITH READ LOCK;</span></span>
<span class="line"><span>SHOW MASTER STATUS;</span></span></code></pre></div><p><strong>注意：</strong> 我们配置主从复制需要 <code>MASTER_LOG_FILE</code> 和 <code>MASTER_LOG_POS</code> 的值，它可以通过 <code>show master status</code> 来获得，因此，你一定要确保你记下了它们的值。</p><p>这些命令运行完成之后，输入 <code>exit</code> 退出这个会话。</p><h3 id="第-2-步-创建一个数据库备份-并将它移动到从服务器上" tabindex="-1">第 2 步 - 创建一个数据库备份，并将它移动到从服务器上 <a class="header-anchor" href="#第-2-步-创建一个数据库备份-并将它移动到从服务器上" aria-label="Permalink to “第 2 步 - 创建一个数据库备份，并将它移动到从服务器上”">​</a></h3><p>现在，我们需要去为我们的数据库 <code>important</code> 创建一个备份，可以使用 <code>mysqldump</code> 命令去备份。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p important &gt; important_backup.sql</span></span></code></pre></div><p>备份完成后，我们需要重新登录到 MariaDB 数据库，并解锁我们的表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>$ UNLOCK TABLES;</span></span></code></pre></div><p>然后退出这个会话。现在，我们移动我们刚才的备份到从服务器上，它的 IP 地址是：192.168.1.130。</p><p>在主服务器上的配置已经完成了，现在，我们开始配置从服务器。</p><h3 id="第-3-步-配置从服务器" tabindex="-1">第 3 步：配置从服务器 <a class="header-anchor" href="#第-3-步-配置从服务器" aria-label="Permalink to “第 3 步：配置从服务器”">​</a></h3><p>我们再次去编辑（从服务器上的） <code>/etc/my.cnf</code> 文件，找到配置文件中的 <code>[mysqld]</code> 节，然后输入如下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[mysqld]</span></span>
<span class="line"><span>server-id = 2</span></span>
<span class="line"><span>replicate-do-db=important</span></span>
<span class="line"><span>[ …]</span></span></code></pre></div><p>现在，我们恢复我们主数据库的备份到从服务器的 MariaDB 上，运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p &lt; /data/ important_backup.sql</span></span></code></pre></div><p>当这个恢复过程结束之后，我们将通过登入到从服务器上的 MariaDB，为数据库 <code>important</code> 上的用户 &#39;slaveuser&#39; 授权。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRANT ALL PRIVILEGES ON important.* TO &#39;slaveuser&#39;@&#39;localhost&#39; WITH GRANT OPTION;</span></span>
<span class="line"><span>FLUSH PRIVILEGES;</span></span></code></pre></div><p>接下来，为了这个变化生效，重启 MariaDB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl restart mariadb</span></span></code></pre></div><h3 id="第-4-步-启动复制" tabindex="-1">第 4 步：启动复制 <a class="header-anchor" href="#第-4-步-启动复制" aria-label="Permalink to “第 4 步：启动复制”">​</a></h3><p>记住，我们需要 <code>MASTER_LOG_FILE</code> 和 <code>MASTER_LOG_POS</code> 变量的值，它可以通过在主服务器上运行 <code>SHOW MASTER STATUS</code> 获得。现在登入到从服务器上的 MariaDB，然后通过运行下列命令，告诉我们的从服务器它应该去哪里找主服务器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STOP SLAVE;</span></span>
<span class="line"><span>CHANGE MASTER TO MASTER_HOST= &#39;192.168.1.110′, MASTER_USER=&#39;slaveuser&#39;, MASTER_PASSWORD=&#39;iamslave&#39;, MASTER_LOG_FILE=&#39;mariadb-bin.000001′, MASTER_LOG_POS=460;</span></span>
<span class="line"><span>SLAVE START;</span></span>
<span class="line"><span>SHOW SLAVE STATUS\\G;</span></span></code></pre></div><p><strong>注意：</strong> 请根据你的机器的具体情况来改变主服务器的配置。</p><h3 id="第-5-步-测试复制" tabindex="-1">第 5 步：测试复制 <a class="header-anchor" href="#第-5-步-测试复制" aria-label="Permalink to “第 5 步：测试复制”">​</a></h3><p>我们将在我们的主服务器上创建一个新表来测试主从复制是否正常工作。因此，登入到主服务器上的 MariaDB。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><p>选择数据库为 <code>important</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>use important;</span></span></code></pre></div><p>在这个数据库上创建一个名为 <code>test</code> 的表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>create table test (c int);</span></span></code></pre></div><p>然后在这个表中插入一些数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>insert into test (c) value (1);</span></span></code></pre></div><p>检索刚才插入的值是否存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>select * from test;</span></span></code></pre></div><p>你将会看到刚才你插入的值已经在这个新建的表中了。</p><p>现在，我们登入到从服务器的数据库中，查看主从复制是否正常工作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>$ use important;</span></span>
<span class="line"><span>$ select * from test;</span></span></code></pre></div><p>你可以看到与前面在主服务器上的命令输出是一样的。因此，说明我们的主从服务工作正常，没有发生任何问题。</p><p>我们的教程结束了，请在下面的评论框中留下你的查询/问题。</p><hr>`,51)),i("p",null,[s[9]||(s[9]=a("via: ",-1)),t(e,{href:"http://linuxtechlab.com/creating-master-slave-replication-mariadb/"},{default:n(()=>[...s[8]||(s[8]=[a("http://linuxtechlab.com/creating-master-slave-replication-mariadb/",-1)])]),_:1})]),i("p",null,[s[13]||(s[13]=a("作者：",-1)),t(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:n(()=>[...s[10]||(s[10]=[a("Shusain",-1)])]),_:1}),s[14]||(s[14]=a(" 译者：",-1)),t(e,{href:"https://github.com/qhwdw"},{default:n(()=>[...s[11]||(s[11]=[a("qhwdw",-1)])]),_:1}),s[15]||(s[15]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[a("Linux中国",-1)])]),_:1}),s[20]||(s[20]=a(" 荣誉推出",-1))])])}const v=l(h,[["render",g]]);export{S as __pageData,v as default};
